func summarizeFollowUp(followUp apiInvestigationFollowUp) apiInvestigationFollowUpBrief {
	brief := apiInvestigationFollowUpBrief{
		Priority: followUp.Step.Priority,
		Tool:     followUp.Step.Tool,
		Status:   followUp.Status,
		Error:    followUp.Error,
	}
	switch result := followUp.Result.(type) {
	case apiTraceResponse:
		brief.Summary = fmt.Sprintf("trace %s.%s: %d direct calls, %d total calls", result.Procedure.Module, result.Procedure.Name, len(result.Calls), countTraceCalls(result.Calls))
	case apiActionEvidenceResponse:
		brief.Summary = fmt.Sprintf("evidence: %d snippets, %d next-hop procedures", len(result.CodeEvidence), len(result.NextHopEvidence))
	case apiMetadataModulesResponse:
		brief.Summary = fmt.Sprintf("object modules: %d", len(result.Modules))
	case apiMetadataEntryTracesResponse:
		brief.Summary = fmt.Sprintf("entry traces: %d", len(result.EntryTraces))
	case apiFTSSearchResponse:
		brief.Summary = fmt.Sprintf("code search: %d total, %d returned", result.Total, len(result.Items))
	case apiMetadataRelationsResponse:
		brief.Summary = fmt.Sprintf("relations %s: %d total, %d returned", result.Direction, result.Total, len(result.Items))
	case apiProcedureSourceResponse:
		brief.Summary = fmt.Sprintf("source %s.%s: lines %d-%d", result.Procedure.Module, result.Procedure.Name, result.Procedure.StartLine, result.Procedure.EndLine)
	}
	return brief
}

func collectFollowUpSummary(summary *apiInvestigationSummaryResponse, followUp apiInvestigationFollowUp, addProcedure func(module, name, reason string)) {
	switch result := followUp.Result.(type) {
	case apiTraceResponse:
		addProcedure(result.Procedure.Module, result.Procedure.Name, "follow-up trace root")
		for _, call := range result.Calls {
			collectTraceCallChains(summary, result.Procedure, call, "follow-up trace edge", addProcedure)
		}
	case apiActionEvidenceResponse:
		for _, evidence := range result.CodeEvidence {
			if evidence.Module != nil && evidence.Procedure != nil {
				addProcedure(*evidence.Module, *evidence.Procedure, "follow-up evidence")
			}
			addKeyLinesFromEvidence(summary, evidence, 20)
		}
	case apiMetadataModulesResponse:
		addObjectModuleCandidates(summary, result.Modules, addProcedure)
	case apiFTSSearchResponse:
		for _, item := range result.Items {
			if item.Module != nil && item.Procedure != nil {
				addProcedure(*item.Module, *item.Procedure, "follow-up code search")
			}
			evidence := apiEvidenceCodeSnippet{
				SourceFile:   item.SourceFile,
				StartLine:    item.Line,
				EndLine:      item.EndLine,
				Module:       item.Module,
				Procedure:    item.Procedure,
				MatchedQuery: item.MatchedQuery,
				MatchedMode:  item.MatchedMode,
			}
			snippetText, lines, matchStartLine, matchEndLine := buildCodeEvidenceSnippet(item.MatchedQuery, item.MatchedMode, item)
			evidence.Text = snippetText
			evidence.Lines = lines
			evidence.MatchStartLine = matchStartLine
			evidence.MatchEndLine = matchEndLine
			addKeyLinesFromEvidence(summary, evidence, 20)
		}
	case apiProcedureSourceResponse:
		addProcedure(result.Procedure.Module, result.Procedure.Name, "follow-up source")
		addKeyLinesFromSource(summary, result.Procedure, result.Source, 20)
	}
}

func addKeyLinesFromSource(summary *apiInvestigationSummaryResponse, procedure apiProcedureDetail, source string, limit int) {
	sourceFile := procedure.SourceFile
	for index, text := range strings.Split(source, "\n") {
		if len(summary.KeyLines) >= limit {
			return
		}
		text = strings.TrimSpace(text)
		if text == "" {
			continue
		}
		appendKeyLine(summary, sourceFile, apiEvidenceLine{
			Line:    procedure.StartLine + index,
			Text:    text,
			Matched: true,
		}, procedure.Module, procedure.Name, "", limit)
	}
}

