func addObjectModuleCandidates(summary *apiInvestigationSummaryResponse, modules []apiMetadataModule, addProcedure func(module, name, reason string)) {
	candidates := rankObjectModuleProcedures(summary.Query, modules, 10)
	if len(candidates) == 0 {
		if len(summary.KeyProcedures) > 0 {
			return
		}
		for _, module := range modules {
			for _, procedure := range module.Procedures {
				addProcedure(procedure.Module, procedure.Name, "object module procedure")
			}
		}
		return
	}
	for _, candidate := range candidates {
		addProcedure(candidate.Procedure.Module, candidate.Procedure.Name, candidate.Reason)
	}
}

func rankObjectModuleProcedures(query string, modules []apiMetadataModule, limit int) []objectModuleProcedureCandidate {
	queryTokens := prioritizeQueryExpansionTokens(queryExpansionTokens(query))
	if len(queryTokens) == 0 {
		return nil
	}
	var candidates []objectModuleProcedureCandidate
	for _, module := range modules {
		moduleScore, moduleBucket, moduleMatches := identifierQueryScoreMetrics(queryTokens, module.ModuleFullName)
		moduleScore = moduleScore / 2
		for _, procedure := range module.Procedures {
			procedureScore, procedureBucket, procedureMatches := identifierQueryScoreMetrics(queryTokens, procedure.Name)
			score := procedureScore + moduleScore
			if score <= 0 {
				continue
			}
			bucket := procedureBucket
			if bucket == "" {
				bucket = moduleBucket
			}
			coverage := len(mergeStringSets(procedureMatches, moduleMatches))
			candidates = append(candidates, objectModuleProcedureCandidate{
				Procedure: procedure,
				Score:     score,
				Bucket:    bucket,
				Coverage:  coverage,
				Reason:    "object module candidate matched query tokens",
			})
		}
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if candidates[i].Score != candidates[j].Score {
			return candidates[i].Score > candidates[j].Score
		}
		left := candidates[i].Procedure.Module + "." + candidates[i].Procedure.Name
		right := candidates[j].Procedure.Module + "." + candidates[j].Procedure.Name
		return left < right
	})
	if limit > 0 && len(candidates) > limit {
		candidates = candidates[:limit]
	}
	return candidates
}

func diverseObjectModuleProcedureCandidates(query string, modules []apiMetadataModule, limit int) []objectModuleProcedureCandidate {
	candidates := rankObjectModuleProcedures(query, modules, 0)
	if limit <= 0 || len(candidates) <= limit {
		return candidates
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if candidates[i].Coverage != candidates[j].Coverage {
			return candidates[i].Coverage > candidates[j].Coverage
		}
		if candidates[i].Score != candidates[j].Score {
			return candidates[i].Score > candidates[j].Score
		}
		left := candidates[i].Procedure.Module + "." + candidates[i].Procedure.Name
		right := candidates[j].Procedure.Module + "." + candidates[j].Procedure.Name
		return left < right
	})
	var result []objectModuleProcedureCandidate
	seenProcedure := map[int64]bool{}
	seenBucket := map[string]bool{}
	for _, candidate := range candidates {
		if candidate.Bucket == "" || seenBucket[candidate.Bucket] || seenProcedure[candidate.Procedure.ID] {
			continue
		}
		result = append(result, candidate)
		seenBucket[candidate.Bucket] = true
		seenProcedure[candidate.Procedure.ID] = true
		if len(result) >= limit {
			return result
		}
	}
	for _, candidate := range candidates {
		if seenProcedure[candidate.Procedure.ID] {
			continue
		}
		result = append(result, candidate)
		seenProcedure[candidate.Procedure.ID] = true
		if len(result) >= limit {
			return result
		}
	}
	return result
}

func prioritizeCandidatesByProcedureContent(ctx context.Context, db *sql.DB, query string, candidates []objectModuleProcedureCandidate, limit int) []objectModuleProcedureCandidate {
	if limit <= 0 || len(candidates) <= limit {
		return candidates
	}
	queryTokens := prioritizeQueryExpansionTokens(queryExpansionTokens(query))
	if len(queryTokens) == 0 {
		return candidates[:limit]
	}
	texts, err := loadProcedureFTSTexts(ctx, db, candidates)
	if err != nil {
		return candidates[:limit]
	}
	scored := append([]objectModuleProcedureCandidate{}, candidates...)
	sort.SliceStable(scored, func(i, j int) bool {
		left := candidateContentAwareScore(queryTokens, scored[i], texts[scored[i].Procedure.ID])
		right := candidateContentAwareScore(queryTokens, scored[j], texts[scored[j].Procedure.ID])
		if left != right {
			return left > right
		}
		if scored[i].Coverage != scored[j].Coverage {
			return scored[i].Coverage > scored[j].Coverage
		}
		if scored[i].Score != scored[j].Score {
			return scored[i].Score > scored[j].Score
		}
		leftName := scored[i].Procedure.Module + "." + scored[i].Procedure.Name
		rightName := scored[j].Procedure.Module + "." + scored[j].Procedure.Name
		return leftName < rightName
	})
	if len(scored) > limit {
		scored = scored[:limit]
	}
	return scored
}

func loadProcedureFTSTexts(ctx context.Context, db *sql.DB, candidates []objectModuleProcedureCandidate) (map[int64]string, error) {
	ids := make([]int64, 0, len(candidates))
	for _, candidate := range candidates {
		ids = append(ids, candidate.Procedure.ID)
	}
	return loadProcedureTextsByID(ctx, db, ids)
}

func candidateContentAwareScore(queryTokens []string, candidate objectModuleProcedureCandidate, text string) int {
	score := candidate.Score + candidate.Coverage*10
	if text == "" {
		return score
	}
	textTokens := identifierTokens(text)
	matched := map[string]bool{}
	for _, queryToken := range queryTokens {
		best := 0
		for _, textToken := range textTokens {
			if itemScore := tokenSimilarityScore(queryToken, textToken); itemScore > best {
				best = itemScore
			}
		}
		if best > 0 {
			matched[queryToken] = true
			score += best
		}
	}
	score += len(matched) * 15
	return score
}

func mergeStringSets(left, right []string) []string {
	seen := map[string]bool{}
	result := make([]string, 0, len(left)+len(right))
	for _, value := range append(left, right...) {
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		result = append(result, value)
	}
	return result
}
